#include "stdafx.h"#include "HcdElementBase.h"struct SNumbConstant_P{#include "PrivateVars/NumbConstant.h"};class KNumbConstant : public KHcdElementBase  , protected SNumbConstant_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );};static KHcdFactory _NumbConstant("NumbConstant", KNumbConstant::Create);IHcdElement *KNumbConstant::Create(){  return new KNumbConstant;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KNumbConstant, 4 )void KNumbConstant::InitParm(){#include "PrivateVars/NumbConstant.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KNumbConstant::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  OUTR0 = atof( szName );}